import { ApiProperty } from '@nestjs/swagger';

/**
 * Standard error response envelope generated by AllExceptionsFilter
 */
export class ErrorResponseDto {
  @ApiProperty({
    description: 'HTTP status code',
    example: 400,
  })
  statusCode: number;

  @ApiProperty({
    description: 'ISO-8601 timestamp of when the error occurred',
    example: '2026-10-27T12:00:00.000Z',
  })
  timestamp: string;

  @ApiProperty({
    description: 'API endpoint path where the error was triggered',
    example: '/api/v1/videos/init',
  })
  path: string;

  @ApiProperty({
    description: 'Standard HTTP error classification name',
    example: 'BadRequestException',
  })
  error: string;

  @ApiProperty({
    description: 'Human-readable error description or details',
    example: 'Storage quota exceeded for current user storage capacity limit',
  })
  message: string;
}

/**
 * Validation error response envelope when class-validator fails
 */
export class ValidationErrorResponseDto {
  @ApiProperty({
    description: 'HTTP status code',
    example: 400,
  })
  statusCode: number;

  @ApiProperty({
    description: 'ISO-8601 timestamp of when the error occurred',
    example: '2026-10-27T12:00:00.000Z',
  })
  timestamp: string;

  @ApiProperty({
    description: 'API endpoint path where the error was triggered',
    example: '/api/v1/videos/init',
  })
  path: string;

  @ApiProperty({
    description: 'Standard HTTP error classification name',
    example: 'Bad Request',
  })
  error: string;

  @ApiProperty({
    description: 'List of validation constraints that failed',
    type: [String],
    example: [
      'title must be a string',
      'size must be a positive integer greater than 0',
      'slug must contain only lowercase alphanumeric characters and hyphens (e.g. my-awesome-video)',
    ],
  })
  message: string[];
}

/**
 * Standard confirmation envelope for delete and revocation operations
 */
export class ActionSuccessResponseDto {
  @ApiProperty({
    description: 'Indicates whether the deletion or revocation succeeded',
    example: true,
  })
  success: boolean;

  @ApiProperty({
    description: 'Unique identifier of the affected resource',
    example: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
  })
  id: string;
}
